import path from 'path';
import fs from 'fs';
import { generateIcons } from './icons.js';
import { log } from '../core/logger.js';
import { copyDirectorySync } from './filesystem.js';
import { writeMainActivity } from './android/mainActivity.js';
import { writeAndroidManifest } from './android/manifest.js';
import { writeStringsXml, writeStylesXml, writeColorsXml, writeNetworkSecurityConfig } from './android/resources.js';
import { writeAppBuildGradle, writeRootBuildGradle, writeSettingsGradle, writeGradleProperties, writeGradleWrapperProps } from './android/gradle.js';
import { writeLocalProperties } from './android/localProperties.js';
import { writeProguardRules } from './android/proguard.js';
export async function generateProject(config) {
    const projectDirectory = path.resolve(process.cwd(), 'webapkify');
    const packagePath = config.appId.replace(/\./g, '/');
    const mainDirectory = path.join(projectDirectory, 'app/src/main');
    const kotlinDirectory = path.join(mainDirectory, `kotlin/${packagePath}`);
    const resDirectory = path.join(mainDirectory, 'res');
    const assetsDirectory = path.join(mainDirectory, 'assets/www');
    log.step('Scaffolding Android project...');
    fs.mkdirSync(kotlinDirectory, { recursive: true });
    fs.mkdirSync(assetsDirectory, { recursive: true });
    fs.mkdirSync(resDirectory, { recursive: true });
    const webSource = path.resolve(process.cwd(), config.webDir ?? './dist');
    if (!fs.existsSync(webSource)) {
        log.error(`webDir not found: ${webSource}`);
        log.dim('Build your web app first (e.g. npm run build / vite build)');
        process.exit(1);
    }
    log.step('Copying web assets...');
    copyDirectorySync(webSource, assetsDirectory);
    log.success('Web assets copied');
    await generateIcons(config, resDirectory);
    const valuesDirectory = path.join(resDirectory, 'values');
    writeStringsXml(config, valuesDirectory);
    writeStylesXml(config, valuesDirectory);
    writeColorsXml(config, valuesDirectory);
    writeNetworkSecurityConfig(config, resDirectory);
    writeMainActivity(config, kotlinDirectory);
    writeAndroidManifest(config, mainDirectory);
    writeAppBuildGradle(config, projectDirectory);
    writeRootBuildGradle(config, projectDirectory);
    writeSettingsGradle(config, projectDirectory);
    writeGradleProperties(config, projectDirectory);
    writeLocalProperties(projectDirectory);
    writeGradleWrapperProps(projectDirectory);
    writeProguardRules(projectDirectory);
    log.success('Project scaffolding complete');
    return projectDirectory;
}
